let me=null,products=[];const $=s=>document.querySelector(s);const esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
async function api(url,opts={}){const h=opts.body instanceof FormData?{}:{"Content-Type":"application/json",...(opts.headers||{})};const r=await fetch(url,{...opts,headers:h});const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.error||"حصل خطأ");return d}
function toast(t){const e=$("#toast");e.textContent=t;e.classList.add("show");setTimeout(()=>e.classList.remove("show"),2800)}
function fbtConfirm(message,yes="تأكيد",danger=false){return new Promise(resolve=>{openModal(`<div class="fbt-confirm"><div class="modal-kicker">FBT SECURITY</div><h2>تأكيد الإجراء</h2><p>${esc(message)}</p><div class="form-two"><button class="${danger?'btn-danger':'btn-main'}" id="fbtConfirmYes">${yes}</button><button class="btn-outline" id="fbtConfirmNo">إلغاء</button></div></div>`);$("#fbtConfirmYes").onclick=()=>{closeModal();resolve(true)};$("#fbtConfirmNo").onclick=()=>{closeModal();resolve(false)}})}
function openModal(html){$("#modalContent").innerHTML=html;$("#modal").classList.remove("hidden")}function closeModal(){$("#modal").classList.add("hidden")}
function showPage(name){if(["owner-products","owner-users","owner-ledger"].includes(name)&&me?.role!=="owner"){toast("القسم ده للمالك فقط");return}document.querySelectorAll(".page").forEach(p=>p.classList.remove("active"));$("#page-"+name)?.classList.add("active");document.querySelectorAll(".nav-item").forEach(b=>b.classList.toggle("active",b.dataset.page===name));if(name==="orders")loadOrders();if(name==="wallet")loadTopups();if(name.startsWith("owner-"))loadAdmin();window.scrollTo({top:0,behavior:"smooth"})}
function openAuth(){openModal(`<div class="modal-kicker">YOUR ACCOUNT</div><h2>أهلاً بيك في FBT</h2><p class="muted">سجّل دخولك أو أنشئ حساب جديد للبدء.</p><form id="authForm"><label>اسم المستخدم<input name="username" required minlength="3" autocomplete="username"></label><label>كلمة المرور<input name="password" type="password" required minlength="10" autocomplete="current-password"></label><div class="form-two"><button class="btn-main" type="button" onclick="authSubmit('login')">تسجيل الدخول</button><button class="btn-outline" type="button" onclick="authSubmit('register')">إنشاء حساب</button></div></form>`)}
async function authSubmit(mode){try{const f=Object.fromEntries(new FormData($("#authForm")));const d=await api("/api/"+mode,{method:"POST",body:JSON.stringify(f)});me=d.user;closeModal();renderAccount();toast(mode==="login"?"تم تسجيل الدخول":"تم إنشاء الحساب");await loadAll()}catch(e){toast(e.message)}}
async function logout(){await api("/api/logout",{method:"POST"});me=null;renderAccount();showPage("home");await loadAll();toast("تم تسجيل الخروج")}
function renderAccount(){const a=$("#account");if(!me){a.innerHTML='<button class="login-btn" onclick="openAuth()">تسجيل الدخول <span>↗</span></button>';$("#balance").innerHTML='— <small>FBT</small>';$ ("#ownerLabel").classList.add("hidden");$("#ownerNav").classList.add("hidden");return}a.innerHTML=`<div class="account-user"><span class="avatar">${esc(me.username.slice(0,1).toUpperCase())}</span><span><b>${esc(me.username)}</b><small>${({owner:"OWNER",vip:"VIP",premium:"PREMIUM",seller:"SELLER",member:"MEMBER",customer:"MEMBER"}[me.role]||"MEMBER")} · ${Number(me.balance).toLocaleString()} FBT</small></span><button onclick="logout()" title="خروج">↗</button></div>`;$("#balance").innerHTML=Number(me.balance).toLocaleString()+" <small>FBT</small>";$("#ownerLabel").classList.toggle("hidden",me.role!=="owner");$("#ownerNav").classList.toggle("hidden",me.role!=="owner")}
async function loadProducts(){products=await api("/api/products");renderProducts();if(me?.role==="owner")renderAdminProducts()}
function renderProducts(){const q=($("#search")?.value||"").toLowerCase();const list=products.filter(p=>(p.name+" "+p.description).toLowerCase().includes(q));$("#productsGrid").innerHTML=list.length?list.map(p=>`<article class="product-card"><div class="product-image">${p.image?`<img src="${esc(p.image)}" alt="${esc(p.name)}">`:'<div class="product-placeholder"><span>F</span><small>FBT EXCLUSIVE</small></div>'}<span class="product-tag">${p.currency==="FBT"?"FBT MONEY":"USD"}</span></div><div class="product-info"><h3>${esc(p.name)}</h3><p>${esc(p.description||"منتج من مجموعة FINAL BREATH.")}</p><div class="product-bottom"><div class="product-price">${Number(p.price).toLocaleString()} <small>${p.currency==="FBT"?"FBT":"USD"}</small></div><button onclick="buyProduct(${p.id})" aria-label="شراء">←</button></div></div></article>`).join(""):'<div class="empty-state">مفيش منتجات مطابقة لبحثك حاليًا.</div>'}
function buyProduct(id){if(!me){openAuth();return}const p=products.find(x=>x.id===id);openModal(`<div class="modal-kicker">ORDER REQUEST</div><h2>طلب ${esc(p.name)}</h2><p class="muted">${esc(p.description||"")}</p><form id="buyForm"><label>اسمك على ديسكورد <input name="discordName" required placeholder="مثال: username أو @username"></label><label>الكمية<input name="quantity" type="number" min="1" max="99" value="1" required></label><label>تفاصيل الطلب<textarea name="details" rows="3" placeholder="أي تفاصيل محتاج توضحها..."></textarea></label><div class="order-total"><span>سعر الوحدة</span><b>${Number(p.price).toLocaleString()} ${p.currency}</b></div><p class="tiny">${p.currency==="FBT"?"سيتم حجز العملات من رصيدك مؤقتًا. لو الطلب اترفض أو انتهت مهلة 72 ساعة هترجع تلقائيًا.":"سيتم إرسال طلبك للمراجعة على ديسكورد."}</p><button class="btn-main full">إرسال الطلب ←</button></form>`);$("#buyForm").onsubmit=async e=>{e.preventDefault();try{const f=Object.fromEntries(new FormData(e.target));const d=await api("/api/orders",{method:"POST",body:JSON.stringify({...f,productId:id})});closeModal();toast(d.message);await loadAll()}catch(err){toast(err.message)}}}
const packs=[[500,2],[1300,4],[2250,6],[4100,10],[7200,16],[10000,22]];function renderPacks(){$("#packs").innerHTML=packs.map(([c,p],i)=>`<button class="pack-card ${i===3?"featured":""}" onclick="buyPack(${c},${p})"><span class="pack-coins">${c.toLocaleString()}</span><b>FBT MONEY</b><span class="pack-price">$${p}</span>${i===3?'<small class="popular">الأكثر اختيارًا</small>':""}</button>`).join("")}
function buyPack(coins,price){if(!me){openAuth();return}openModal(`<div class="modal-kicker">WALLET TOP-UP</div><h2>شحن ${coins.toLocaleString()} FBT</h2><p class="muted">قيمة الباقة: $${price}</p><form id="topupForm"><label>اسمك على ديسكورد<input name="discordName" required placeholder="مثال: username أو @username"></label><label>طريقة الدفع<select name="method" required><option value="">اختار طريقة الدفع</option><option>Vodafone Cash</option><option>InstaPay</option><option>PayPal</option><option>تحويل بنكي</option><option>طريقة أخرى</option></select></label><label>رقم العملية / إثبات الدفع<textarea name="proof" rows="3" placeholder="اكتب رقم العملية أو تفاصيل التحويل"></textarea></label><div class="order-total"><span>العملات اللي هتضاف بعد القبول</span><b>${coins.toLocaleString()} FBT</b></div><button class="btn-main full">إرسال طلب الشحن ←</button></form>`);$("#topupForm").onsubmit=async e=>{e.preventDefault();try{const d=await api("/api/topups",{method:"POST",body:JSON.stringify({...Object.fromEntries(new FormData(e.target)),coins})});closeModal();toast(d.message);loadTopups()}catch(err){toast(err.message)}}}
function statusLabel(s){return ({pending:"قيد المراجعة",paid:"مدفوع",processing:"قيد التنفيذ",completed:"مكتمل",cancelled:"ملغي",rejected:"مرفوض",approved:"تم القبول",accepted:"تم القبول"})[s]||s}
async function loadOrders(){if(!me){$("#ordersList").textContent="سجّل الدخول لعرض طلباتك.";return}try{const a=await api("/api/orders");$("#ordersList").innerHTML=a.length?a.map(o=>`<div class="history-row"><div><b>${esc(o.product_name)} × ${o.quantity}</b><small>طلب #${o.id} · ${esc(o.created_at)} · ${esc(o.discord_name)}</small></div><div class="history-meta"><b>${Number(o.total).toLocaleString()} ${o.currency}</b><span class="status ${o.status}">${statusLabel(o.status)}${o.refunded?" · تم رد العملات":""}</span></div></div>`).join(""):'<div class="empty-state compact">لسه معندكش مشتريات.</div>'}catch(e){toast(e.message)}}
async function loadTopups(){if(!me){$("#topupsHistory").textContent="سجّل الدخول لعرض طلبات الشحن.";return}try{const a=await api("/api/topups");$("#topupsHistory").innerHTML=a.length?a.map(t=>`<div class="history-row"><div><b>${Number(t.coins).toLocaleString()} FBT MONEY</b><small>طلب شحن #${t.id} · ${esc(t.method)} · ${esc(t.discord_name)}</small></div><div class="history-meta"><b>$${esc(t.amount)}</b><span class="status ${t.status}">${statusLabel(t.status)}</span></div></div>`).join(""):'<div class="empty-state compact">مفيش طلبات شحن حتى الآن.</div>'}catch(e){toast(e.message)}}
function renderAdminProducts(){$("#adminProducts").innerHTML=products.map(p=>`<div class="manage-row"><div><b>${esc(p.name)}</b><small>${Number(p.price).toLocaleString()} ${p.currency}</small></div><button class="btn-danger small" onclick="deleteProduct(${p.id})">إخفاء</button></div>`).join("")||'<div class="empty-state compact">لا توجد منتجات منشورة.</div>'}
async function deleteProduct(id){if(!await fbtConfirm("حذف المنتج نهائيًا من المتجر؟ لن يظهر مرة أخرى في القائمة.","حذف",true))return;try{await api("/api/admin/products/"+id,{method:"DELETE"});toast("تم إخفاء المنتج");loadProducts()}catch(e){toast(e.message)}}
async function loadAdmin(){if(me?.role!=="owner")return;try{const [users,ledger]=await Promise.all([api("/api/admin/users"),api("/api/admin/ledger")]);$("#customerNames").innerHTML=users.filter(u=>u.role!=="owner").map(u=>`<option value="${esc(u.username)}"></option>`).join("");$("#usersList").innerHTML=users.map(u=>`<div class="manage-row"><div><b>${esc(u.username)} ${u.role==="owner"?"· OWNER":""}</b><small>حساب #${u.id}</small></div><strong>${Number(u.balance).toLocaleString()} FBT</strong></div>`).join("")||'<div class="empty-state compact">لا يوجد عملاء.</div>';$("#ledgerList").innerHTML=ledger.map(l=>`<div class="history-row"><div><b>${esc(l.username)}</b><small>${esc(l.reason)} · ${esc(l.created_at)}</small></div><strong class="${l.amount>=0?"positive":"negative"}">${l.amount>0?"+":""}${Number(l.amount).toLocaleString()} FBT</strong></div>`).join("")||'<div class="empty-state compact">لا توجد حركات مسجلة.</div>'}catch(e){toast(e.message)}}
async function changeCoins(sign){const username=$("#coinUsername").value.trim(),amount=Number($("#coinAmount").value)*sign,reason=$("#coinReason").value;if(!username||!Number.isInteger(amount)||!amount)return toast("اكتب اسم العميل والمبلغ بشكل صحيح");if(!await fbtConfirm((sign>0?"إضافة ":"خصم ")+Math.abs(amount)+" عملة إلى حساب "+username+"؟","تأكيد"))return;try{await api("/api/admin/coins",{method:"POST",body:JSON.stringify({username,amount,reason})});toast("تم تحديث الرصيد");$("#coinAmount").value="";$("#coinUsername").value="";loadAdmin();if(me) {const d=await api("/api/me");me=d.user;renderAccount()}}catch(e){toast(e.message)}}
$("#productForm").onsubmit=async e=>{e.preventDefault();try{await api("/api/admin/products",{method:"POST",body:new FormData(e.target)});e.target.reset();toast("تم نشر المنتج بنجاح");await loadProducts()}catch(err){toast(err.message)}};
async function loadAll(){try{const d=await api("/api/me");me=d.user;renderAccount();await loadProducts();renderPacks();await loadOrders();await loadTopups();await loadRanks();if(me?.role==="owner")await loadAdmin()}catch(e){toast(e.message)}}
async function toggleMusic(){const a=$("#bgMusic"),b=$("#musicBtn");if(a.paused){try{await a.play();b.textContent="♫ إيقاف الموسيقى"}catch(e){toast("ضيف ملف music.mp3 داخل مجلد public لتشغيل الموسيقى")}}else{a.pause();b.textContent="♫ تشغيل الموسيقى"}}
loadAll();


// Daily featured products: same three products for everyone on a given UTC day.
function dailyFeatured(){const host=document.querySelector('#featuredProducts');if(!host)return;if(!products.length){host.innerHTML='<div class="empty-state compact">أضف منتجات من لوحة المالك لعرضها هنا.</div>';return;}const day=Math.floor(Date.now()/86400000);let seed=(day+1)*2654435761>>>0;const sorted=[...products];for(let i=sorted.length-1;i>0;i--){seed=(seed*1664525+1013904223)>>>0;const j=seed%(i+1);[sorted[i],sorted[j]]=[sorted[j],sorted[i]];}const picks=sorted.slice(0,3);host.innerHTML=picks.map(p=>`<article class="featured-card"><img src="${esc(p.image||'')||'data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 width=%22600%22 height=%22300%22%3E%3Crect width=%22100%25%22 height=%22100%25%22 fill=%22%23131619%22/%3E%3Ctext x=%2250%25%22 y=%2255%25%22 text-anchor=%22middle%22 fill=%22white%22 font-size=%2270%22 font-family=%22Arial%22%3EFBT%3C/text%3E%3C/svg%3E'}" alt="${esc(p.name)}"><div class="featured-info"><h3>${esc(p.name)}</h3><span class="featured-price">${Number(p.price).toLocaleString()} ${p.currency}</span><button onclick="buyProduct(${p.id})">شراء الآن</button></div></article>`).join('');}
const _loadProductsOriginal=loadProducts;loadProducts=async function(){await _loadProductsOriginal();dailyFeatured()};
let fbtLanguage='ar';function toggleLanguage(){fbtLanguage=fbtLanguage==='ar'?'en':'ar';const en=fbtLanguage==='en';document.documentElement.lang=en?'en':'ar';document.documentElement.dir=en?'ltr':'rtl';const t={mainMenuLabel:en?'MAIN MENU':'القائمة الرئيسية',featuredTitle:en?"Today's Picks":'اختيارات اليوم',featuredSubtitle:en?'Three featured products refreshed daily':'ثلاثة منتجات مختارة تتجدد كل يوم',featuredAll:en?'All products →':'كل المنتجات ←',langToggle:en?'العربية':'English'};Object.entries(t).forEach(([id,v])=>{const e=document.getElementById(id);if(e)e.textContent=v});const nav=document.querySelectorAll('.side-nav .nav-item');const ar=['الرئيسية','المنتجات','محفظة FBT','طلباتي','إدارة المنتجات','العملاء والأرصدة','سجل العملات'],eng=['Home','Products','FBT Wallet','My Orders','Manage Products','Customers & Balances','Coin Ledger'];nav.forEach((b,i)=>{const icon=b.querySelector('i')?.outerHTML||'';b.innerHTML=icon+' '+(en?eng[i]:ar[i]||eng[i])});const side=document.querySelector('.brand small');if(side)side.textContent=en?'PREMIUM STORE':'متجر مميز';const mobile=document.querySelector('.mobile-login');if(mobile)mobile.textContent=en?'Account':'حسابي';document.querySelector('.welcome-row .eyebrow').textContent=en?'THE NEXT LEVEL OF SHOPPING':'THE NEXT LEVEL OF SHOPPING';document.querySelector('.welcome-row h1').innerHTML=en?'Everything you need,<br><em>in one place.</em>':'كل اللي بتدور عليه،<br><em>في مكان واحد.</em>';document.querySelector('.welcome-row .lead').textContent=en?'Discover our collection, track purchases, and manage your balance in one place.':'اكتشف مجموعتنا، تابع مشترياتك، وتحكم في رصيدك من تجربة واحدة.';const acts=document.querySelectorAll('.hero-actions button');if(acts[0])acts[0].innerHTML=en?'Browse products <span>←</span>':'تصفح المنتجات <span>←</span>';if(acts[1])acts[1].textContent=en?'Top up wallet':'اشحن المحفظة';document.querySelector('#page-products .page-heading h1').textContent=en?'Products':'المنتجات';document.querySelector('#page-products .page-heading>div>p:not(.eyebrow)').textContent=en?'All available products in the store.':'كل المنتجات المتاحة في المتجر.';document.querySelector('#search').placeholder=en?'Search products...':'ابحث عن منتج...';document.querySelector('#page-wallet .page-heading h1').textContent=en?'FBT Wallet':'محفظة FBT';document.querySelector('#page-orders .page-heading h1').textContent=en?'My Orders':'طلباتي';document.querySelector('#page-owner-users .page-heading h1').textContent=en?'Customers & Balances':'العملاء والأرصدة';dailyFeatured();}


// FBT 2.0 storefront enhancements
let cart=[];
function roleName(role){return ({customer:"MEMBER",member:"MEMBER",vip:"VIP",premium:"PREMIUM",seller:"SELLER",owner:"OWNER",banned:"BANNED"}[role]||"MEMBER")}
function roleClass(role){return "rank-"+(role||"customer")}
const _renderAccountV1=renderAccount;
renderAccount=function(){_renderAccountV1();if(me){const label=roleName(me.role);const small=$("#account .account-user small");if(small){small.textContent=label+" · "+Number(me.balance).toLocaleString()+" FBT";small.className=roleClass(me.role)}const av=$("#account .avatar");if(av)av.classList.add(roleClass(me.role));}};
showPage=function(name){const admin=["owner-products","owner-users","owner-ledger","owner-orders","owner-topups","owner-ranks","owner-coupons","owner-settings"];if(admin.includes(name)&&me?.role!=="owner"){toast("القسم ده للمالك فقط");return}document.querySelectorAll(".page").forEach(p=>p.classList.remove("active"));$("#page-"+name)?.classList.add("active");document.querySelectorAll(".nav-item").forEach(b=>b.classList.toggle("active",b.dataset.page===name));if(name==="orders")loadOrders();if(name==="wallet")loadTopups();if(name==="cart")renderCart();if(name.startsWith("owner-"))loadAdmin();window.scrollTo({top:0,behavior:"smooth"})};
renderProducts=function(){const q=($("#search")?.value||"").toLowerCase();const list=products.filter(p=>(p.name+" "+p.description).toLowerCase().includes(q));$("#productsGrid").innerHTML=list.length?list.map(p=>`<article class="product-card"><div class="product-image">${p.image?`<img src="${esc(p.image)}" alt="${esc(p.name)}">`:'<div class="product-placeholder"><span>F</span><small>FBT EXCLUSIVE</small></div>'}<span class="product-tag">${p.currency==="FBT"?"FBT MONEY":"USD"}</span></div><div class="product-info"><h3>${esc(p.name)}</h3><p>${esc(p.description||"منتج من مجموعة FINAL BREATH.")}</p><div class="product-bottom"><div class="product-price">${Number(p.price).toLocaleString()} <small>${p.currency==="FBT"?"FBT":"USD"}</small></div><button onclick="addToCart(${p.id})" aria-label="إضافة للسلة">＋</button></div></div></article>`).join(""):'<div class="empty-state">مفيش منتجات مطابقة لبحثك حاليًا.</div>'};
function addToCart(id){if(!me){openAuth();return}const p=products.find(x=>x.id===id);if(!p)return;const row=cart.find(x=>x.id===id);if(row)row.quantity=Math.min(99,row.quantity+1);else cart.push({id,quantity:1});updateCartCount();toast("تمت إضافة المنتج للسلة");}
function updateCartCount(){const el=$("#cartCount");if(el)el.textContent=cart.reduce((s,x)=>s+x.quantity,0)}
async function renderCart(){const host=$("#cartItems");if(!cart.length){host.innerHTML='<div class="empty-state">سلة المشتريات فارغة.</div>';$("#cartTotal").textContent="0";$("#cartPaymentInfo").innerHTML="";return}const rows=cart.map(x=>({...x,p:products.find(p=>p.id===x.id)})).filter(x=>x.p);$("#beginCheckoutBtn")?.classList.toggle("hidden",checkoutOpen);$("#cartCheckoutFields")?.classList.toggle("hidden",!checkoutOpen);host.innerHTML=rows.map(x=>`<div class="manage-row cart-row"><div><b>${esc(x.p.name)}</b><small>${x.p.price} ${x.p.currency} × ${x.quantity}</small></div><div class="cart-qty"><button onclick="changeCartQty(${x.id},-1)">−</button><b>${x.quantity}</b><button onclick="changeCartQty(${x.id},1)">＋</button><button class="btn-danger small" onclick="removeCart(${x.id})">×</button></div></div>`).join("");const totals=rows.reduce((s,x)=>{s[x.p.currency]=(s[x.p.currency]||0)+x.p.price*x.quantity;return s;},{});$("#cartTotal").textContent=Object.entries(totals).map(([c,v])=>v.toLocaleString()+" "+c).join(" + ");const usd=rows.some(x=>x.p.currency==="USD");if(usd){try{const c=await api("/api/store-config");$("#cartPaymentInfo").innerHTML=`<div class="instapay-note"><b>الدفع بالدولار عبر InstaPay</b><p>رقم التحويل: ${esc(c.instapay_number||"يتم تحديده من الإدارة")}</p><p>اسم المستلم: ${esc(c.instapay_name||"FINAL BREATH STORE")}</p><small>اكتب رقم العملية في خانة التفاصيل قبل إرسال الطلب.</small></div>`}catch{}}else $("#cartPaymentInfo").innerHTML="";}
function changeCartQty(id,d){const x=cart.find(a=>a.id===id);if(!x)return;x.quantity=Math.max(1,Math.min(99,x.quantity+d));renderCart();updateCartCount()}
function removeCart(id){cart=cart.filter(x=>x.id!==id);renderCart();updateCartCount()}
async function checkoutCart(){if(!me){openAuth();return}if(!cart.length)return toast("السلة فارغة");const discord=$("#cartDiscord").value.trim();if(discord.length<2)return toast("اكتب اسمك على ديسكورد");try{const d=await api("/api/cart/orders",{method:"POST",body:JSON.stringify({items:cart,discordName:discord,details:$("#cartDetails").value,coupon:$("#cartCoupon").value})});cart=[];updateCartCount();renderCart();toast(d.message);await loadAll();showPage("orders")}catch(e){toast(e.message)}}
renderPacks=async function(){const packs=await api("/api/packs");$("#packs").innerHTML=packs.map((p,i)=>`<button class="pack-card ${i===3?"featured":""}" onclick="buyPack(${p.coins},${p.price})"><span class="pack-coins">${Number(p.coins).toLocaleString()}${p.bonus?` + ${p.bonus}`:""}</span><b>FBT MONEY</b><span class="pack-price">$${p.price}</span>${i===3?'<small class="popular">الأكثر اختيارًا</small>':""}</button>`).join("")||'<div class="empty-state">لا توجد باقات متاحة حاليًا.</div>'};
buyPack=async function(coins,price){if(!me){openAuth();return}let cfg={},bonus=0;try{cfg=await api("/api/store-config");const pp=await api("/api/packs");bonus=pp.find(x=>Number(x.coins)===Number(coins))?.bonus||0}catch{}openModal(`<div class="modal-kicker">WALLET TOP-UP</div><h2>شحن ${Number(coins).toLocaleString()} FBT</h2><p class="muted">قيمة الباقة: $${price}</p><div class="instapay-note"><b>الدفع عبر InstaPay</b><p>رقم التحويل: ${esc(cfg.instapay_number||"يتم تحديده من الإدارة")}</p><p>اسم المستلم: ${esc(cfg.instapay_name||"FINAL BREATH STORE")}</p></div><form id="topupForm"><label>اسمك على ديسكورد<input name="discordName" required placeholder="مثال: username أو @username"></label><label>طريقة الدفع<select name="method" required><option>InstaPay</option><option>تحويل بنكي</option><option>طريقة أخرى</option></select></label><label>رقم العملية / إثبات الدفع<textarea name="proof" rows="3"></textarea></label><div class="order-total"><span>العملات بعد القبول</span><b>${(Number(coins)+Number(bonus)).toLocaleString()} FBT${bonus?` (تشمل ${bonus} بونص)`:""}</b></div><button class="btn-main full">إرسال طلب الشحن ←</button></form>`);$("#topupForm").onsubmit=async e=>{e.preventDefault();try{const d=await api("/api/topups",{method:"POST",body:JSON.stringify({...Object.fromEntries(new FormData(e.target)),coins})});closeModal();toast(d.message);loadTopups()}catch(err){toast(err.message)}}};
async function adminAction(url,body){await api(url,{method:"PATCH",body:JSON.stringify(body)});toast("تم تنفيذ العملية");await loadAdmin();const meData=await api("/api/me");me=meData.user;renderAccount()}
loadAdmin=async function(){if(me?.role!=="owner")return;try{
 const [users,ledger,orders,topups,coupons,settings,allProducts]=await Promise.all([api("/api/admin/users"),api("/api/admin/ledger"),api("/api/admin/orders"),api("/api/admin/topups"),api("/api/admin/coupons"),api("/api/admin/settings"),api("/api/admin/all-products")]);
 $("#customerNames").innerHTML=users.filter(u=>u.role!=="owner").map(u=>`<option value="${esc(u.username)}"></option>`).join("");
 $("#usersList").innerHTML=users.map(u=>`<div class="manage-row user-manage"><div><b>${esc(u.username)} <span class="${roleClass(u.role)}">${roleName(u.role)}</span></b><small>حساب #${u.id} · ${Number(u.balance).toLocaleString()} FBT ${u.banned_permanent?"· محظور دائمًا":u.ban_until?"· محظور مؤقتًا":""}</small></div>${u.role==="owner"?"":`<div class="user-actions"><select onchange="adminAction('/api/admin/users/${u.id}',{role:this.value})"><option value="customer" ${u.role==="customer"?"selected":""}>MEMBER</option><option value="vip" ${u.role==="vip"?"selected":""}>VIP</option><option value="premium" ${u.role==="premium"?"selected":""}>PREMIUM</option><option value="seller" ${u.role==="seller"?"selected":""}>SELLER</option></select>${(u.banned_permanent||u.ban_until)?`<button class="btn-outline small" onclick="adminAction('/api/admin/users/${u.id}',{action:'unban',role:'customer'})">فك الحظر</button>`:`<button class="btn-danger small" onclick="banUser(${u.id})">حظر</button>`}</div>`}</div>`).join("");
 $("#ledgerList").innerHTML=ledger.map(l=>`<div class="history-row"><div><b>${esc(l.username)}</b><small>${esc(l.reason)} · ${esc(l.created_at)}</small></div><strong class="${l.amount>=0?"positive":"negative"}">${l.amount>0?"+":""}${Number(l.amount).toLocaleString()} FBT</strong></div>`).join("");
 $("#adminOrders").innerHTML=orders.map(o=>`<div class="history-row"><div><b>#${o.id} · ${esc(o.product_name)} × ${o.quantity}</b><small>${esc(o.username)} · Discord: ${esc(o.discord_name)} · ${esc(o.created_at)} · ${Number(o.total).toLocaleString()} ${o.currency}</small><small>${esc(o.details||"")}</small></div><div class="history-meta"><span class="status ${o.status}">${statusLabel(o.status)}</span>${o.status==="pending"?`<button class="btn-main small" onclick="reviewOrder(${o.id},'accepted')">قبول</button><button class="btn-danger small" onclick="reviewOrder(${o.id},'rejected')">رفض</button>`:""}</div></div>`).join("")||'<div class="empty-state">لا توجد طلبات.</div>';
 $("#adminTopups").innerHTML=topups.map(t=>`<div class="history-row"><div><b>#${t.id} · ${Number(t.coins).toLocaleString()} FBT</b><small>${esc(t.username)} · ${esc(t.discord_name)} · ${esc(t.method)} · $${esc(t.amount)}</small><small>${esc(t.proof||"")}</small></div><div class="history-meta"><span class="status ${t.status}">${statusLabel(t.status)}</span>${t.status==="pending"?`<button class="btn-main small" onclick="reviewTopup(${t.id},'accepted')">قبول وإضافة</button><button class="btn-danger small" onclick="reviewTopup(${t.id},'rejected')">رفض</button>`:""}</div></div>`).join("")||'<div class="empty-state">لا توجد طلبات شحن.</div>';
 $("#couponsList").innerHTML=coupons.map(c=>`<div class="manage-row"><div><b>${esc(c.code)} · ${c.type==="percent"?c.value+"%":c.value}</b><small>الاستخدام ${c.uses}${c.max_uses?"/"+c.max_uses:""} · ${c.active?"فعال":"متوقف"}</small></div><div><button class="btn-outline small" onclick="toggleCoupon(${c.id},${!c.active})">${c.active?"إيقاف":"تفعيل"}</button><button class="btn-danger small" onclick="deleteCoupon(${c.id})">حذف</button></div></div>`).join("")||'<div class="empty-state">لا توجد أكواد.</div>';
 $("#adminProducts").innerHTML=allProducts.map(p=>`<div class="manage-row"><div><b>${esc(p.name)}</b><small>${Number(p.price).toLocaleString()} ${p.currency} · ${p.active?"منشور":"مخفي"}</small></div><div><button class="btn-outline small" onclick="editProduct(${p.id})">تعديل</button><button class="btn-outline small" onclick="toggleProduct(${p.id},${p.active?0:1})">${p.active?"إخفاء":"إظهار"}</button></div></div>`).join("");
 const sf=$("#settingsForm");if(sf){for(const [k,v] of Object.entries(settings.settings))if(sf.elements[k])sf.elements[k].value=v;$("#packsAdmin").innerHTML=settings.packs.map(p=>`<div class="pack-admin-row"><label>العملات<input data-pack-coins="${p.coins}" value="${p.coins}" type="number"></label><label>السعر $<input data-pack-price="${p.coins}" value="${p.price}"></label><label>بونص<input data-pack-bonus="${p.coins}" value="${p.bonus}" type="number"></label><label><input data-pack-active="${p.coins}" type="checkbox" ${p.active?"checked":""}> فعال</label></div>`).join("")}
 }catch(e){toast(e.message)}};
async function reviewOrder(id,status){if(!await fbtConfirm(status==="accepted"?"تأكيد قبول الطلب؟":"رفض الطلب وإرجاع رصيد FBT إن وجد؟",status==="accepted"?"قبول":"رفض",status!=="accepted"))return;await adminAction("/api/admin/orders/"+id,{status})}
async function reviewTopup(id,status){if(!await fbtConfirm(status==="accepted"?"قبول الشحن وإضافة العملات؟":"رفض طلب الشحن؟",status==="accepted"?"قبول":"رفض",status!=="accepted"))return;await adminAction("/api/admin/topups/"+id,{status})}
async function banUser(id){openModal(`<div class="modal-kicker">ACCOUNT SECURITY</div><h2>إعداد الحظر</h2><form id="banForm"><label>نوع الحظر<select name="kind"><option value="temporary">مؤقت</option><option value="permanent">دائم</option></select></label><label>المدة بالساعات<input name="hours" type="number" min="1" value="24"></label><label>سبب الحظر<input name="reason" value="مخالفة القوانين" required></label><div class="form-two"><button class="btn-danger">تأكيد الحظر</button><button type="button" class="btn-outline" onclick="closeModal()">إلغاء</button></div></form>`);$("#banForm").onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));closeModal();await adminAction("/api/admin/users/"+id,{action:"ban",permanent:f.kind==="permanent",hours:Number(f.hours)||24,reason:f.reason})}}
async function toggleCoupon(id,active){await api("/api/admin/coupons/"+id,{method:"PATCH",body:JSON.stringify({active})});loadAdmin()}
async function deleteCoupon(id){if(await fbtConfirm("حذف الكوبون؟","حذف",true)){await api("/api/admin/coupons/"+id,{method:"DELETE"});loadAdmin()}}
async function toggleProduct(id,active){await api("/api/admin/products/"+id,{method:"PATCH",body:JSON.stringify({active:!!active})});loadAdmin();loadProducts()}
async function editProduct(id){const p=(await api("/api/admin/all-products")).find(x=>x.id===id);if(!p)return;const name=prompt("اسم المنتج:",p.name);if(name===null)return;const price=Number(prompt("السعر:",p.price));if(!Number.isInteger(price)||price<1)return toast("السعر غير صحيح");const description=prompt("الوصف:",p.description);if(description===null)return;const currency=prompt("العملة (FBT أو USD):",p.currency);if(!["FBT","USD"].includes(String(currency||"").toUpperCase()))return toast("العملة لازم تكون FBT أو USD");await api("/api/admin/products/"+id,{method:"PATCH",body:JSON.stringify({name,price,description,currency:String(currency).toUpperCase(),active:!!p.active})});loadAdmin();loadProducts()}
$("#couponForm").onsubmit=async e=>{e.preventDefault();try{await api("/api/admin/coupons",{method:"POST",body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});e.target.reset();toast("تم إنشاء الكوبون");loadAdmin()}catch(err){toast(err.message)}};
$("#settingsForm").onsubmit=async e=>{e.preventDefault();const settings=Object.fromEntries(new FormData(e.target));const packs=[...document.querySelectorAll("[data-pack-coins]")].map(el=>{const c=el.dataset.packCoins;return {coins:Number(el.value),price:document.querySelector(`[data-pack-price="${c}"]`).value,bonus:Number(document.querySelector(`[data-pack-bonus="${c}"]`).value),active:document.querySelector(`[data-pack-active="${c}"]`).checked}});try{await api("/api/admin/settings",{method:"PUT",body:JSON.stringify({settings,packs})});toast("تم حفظ الإعدادات");await loadAdmin();renderPacks()}catch(err){toast(err.message)}};

function buyProduct(id){addToCart(id);showPage("cart")}


