function filterCustomers(){const q=($("#customerSearch")?.value||"").trim().toLowerCase();document.querySelectorAll("#usersList .user-manage").forEach(el=>el.classList.toggle("hidden",!el.dataset.search?.includes(q)));}
const _loadAdminRefined=loadAdmin;
loadAdmin=async function(){await _loadAdminRefined();try{const published=await api("/api/admin/all-products");$("#adminProducts").innerHTML=published.map(p=>`<div class="admin-product-card"><img src="${esc(p.image||"")}" alt=""><div><b>${esc(p.name)}</b><small>${p.pricing_mode==="BOTH"?`${p.price_fbt} FBT · $${p.price_usd}`:`${p.price} ${p.currency}`} · منشور</small></div><div class="admin-product-actions"><button class="btn-outline small" onclick="editProductAdvanced(${p.id})">تعديل</button><button class="btn-danger small" onclick="deleteProduct(${p.id})">حذف نهائي</button></div></div>`).join("")||'<div class="empty-state">لا توجد منتجات منشورة.</div>';}catch{}document.querySelectorAll("#usersList .user-manage").forEach(el=>el.dataset.search=el.textContent.toLowerCase());filterCustomers();const packHost=$("#packsAdmin");if(packHost&&!$("#addPackBtn")){const b=document.createElement("button");b.id="addPackBtn";b.type="button";b.className="btn-outline full";b.textContent="＋ إضافة باقة جديدة";b.onclick=()=>{const c=prompt("عدد العملات في الباقة:");if(!c)return;const pr=prompt("السعر بالدولار:");if(pr===null)return;const bo=prompt("البونص (0 لو مفيش):","0")||"0";const row=document.createElement("div");row.className="pack-admin-row";row.innerHTML=`<label>العملات<input data-pack-coins="${esc(c)}" type="number" value="${esc(c)}"></label><label>السعر $<input data-pack-price="${esc(c)}" value="${esc(pr)}"></label><label>بونص<input data-pack-bonus="${esc(c)}" type="number" value="${esc(bo)}"></label><label><input data-pack-active="${esc(c)}" type="checkbox" checked> فعال</label><button type="button" class="btn-danger small" onclick="this.parentElement.remove()">حذف</button>`;packHost.appendChild(row);};packHost.appendChild(b);}document.querySelectorAll("#packsAdmin .pack-admin-row").forEach(row=>{if(!row.querySelector(".pack-remove")){const b=document.createElement("button");b.type="button";b.className="btn-danger small pack-remove";b.textContent="حذف الباقة";b.onclick=()=>row.remove();row.appendChild(b);}});};
const _settingsSubmitOld=$("#settingsForm").onsubmit;
$("#settingsForm").onsubmit=async e=>{e.preventDefault();const settings=Object.fromEntries(new FormData(e.target));const packs=[...document.querySelectorAll("[data-pack-coins]")].map(el=>{const c=el.dataset.packCoins;return {coins:Number(el.value),price:document.querySelector(`[data-pack-price="${c}"]`)?.value||"0",bonus:Number(document.querySelector(`[data-pack-bonus="${c}"]`)?.value||0),active:!!document.querySelector(`[data-pack-active="${c}"]`)?.checked};});try{await api("/api/admin/settings",{method:"PUT",body:JSON.stringify({settings,packs})});toast("تم حفظ الإعدادات والباقات");await loadAdmin();renderPacks();}catch(err){toast(err.message)}};
renderProducts=function(){const q=($("#search")?.value||"").toLowerCase();const list=products.filter(p=>(p.name+" "+p.description).toLowerCase().includes(q));$("#productsGrid").innerHTML=list.length?list.map(p=>{const mode=p.pricing_mode||p.currency,price=mode==="BOTH"?`<span class="price-line">${Number(p.price_usd||0).toFixed(2)} $</span><span class="price-line">${Number(p.price_fbt||p.price).toLocaleString()} FBT</span>`:mode==="USD"?`$${Number(p.price_usd||p.price).toFixed(2)}`:`${Number(p.price_fbt||p.price).toLocaleString()} FBT`;return `<article class="product-card refined-product"><div class="product-open" role="button" tabindex="0" onclick="openProductDetails(${p.id})"><div class="product-image">${p.image?`<img src="${esc(p.image)}" alt="${esc(p.name)}" style="object-position:${Number(p.crop_x??50)}% ${Number(p.crop_y??50)}%">`:'<div class="product-placeholder"><span>F</span><small>FBT EXCLUSIVE</small></div>'}<span class="product-tag">${mode==="BOTH"?"USD + FBT":mode==="USD"?"USD":"FBT MONEY"}</span></div><div class="product-info"><h3>${esc(p.name)}</h3><p>${esc(p.short_description||String(p.description||"").split(/\s+/).slice(0,20).join(" "))}</p><div class="product-price">${price}</div><div class="rating-stars product-rating" aria-label="تقييم المنتج">${[1,2,3,4,5].map(n=>`<button class="rating-star ${n<=Math.round(Number(p.rating_avg||0))?'rated':''}" onclick="event.stopPropagation();rateProduct(${p.id},${n})" title="قيّم ${n} نجوم">★</button>`).join("")}<small>${Number(p.rating_avg||0).toFixed(1)} (${p.rating_count||0})</small></div></div></div><div class="product-card-actions"><button class="btn-main small" onclick="addToCart(${p.id})">إضافة للسلة</button><button class="btn-outline small" onclick="openProductDetails(${p.id})">التفاصيل</button></div></article>`}).join(""):'<div class="empty-state">مفيش منتجات مطابقة لبحثك حاليًا.</div>';};
function openProductDetails(id){const p=products.find(x=>x.id===id);if(!p)return;const mode=p.pricing_mode||p.currency;const price=mode==="BOTH"?`<span class="price-line">$${Number(p.price_usd||0).toFixed(2)}</span><span class="price-line">${Number(p.price_fbt||p.price).toLocaleString()} FBT</span>`:mode==="USD"?`<span class="price-line">$${Number(p.price_usd||p.price).toFixed(2)}</span>`:`<span class="price-line">${Number(p.price_fbt||p.price).toLocaleString()} FBT</span>`;openModal(`<div class="product-detail"><div class="product-detail-image">${p.image?`<img src="${esc(p.image)}" style="object-position:${Number(p.crop_x??50)}% ${Number(p.crop_y??50)}%">`:"FBT"}</div><p class="eyebrow">PRODUCT DETAILS</p><h2>${esc(p.name)}</h2><div class="product-detail-price">${price}</div><p>${esc(p.description||p.short_description||"لا يوجد وصف إضافي.")}</p><div class="rating-stars large">★★★★★ <small>${Number(p.rating_avg||0).toFixed(1)} · ${p.rating_count||0} تقييم</small></div><div class="rate-control"><span>قيّم المنتج:</span>${[1,2,3,4,5].map(n=>`<button onclick="rateProduct(${id},${n})" aria-label="${n} نجوم">★</button>`).join("")}</div><button class="btn-main full" onclick="closeModal();addToCart(${id})">إضافة للسلة</button></div>`);}
async function rateProduct(id,rating){if(!me){openAuth();return}try{await api(`/api/products/${id}/rating`,{method:"POST",body:JSON.stringify({rating})});await loadProducts();toast("تم تسجيل تقييمك بنجاح");}catch(e){toast(e.message)}}
let checkoutOpen=false;function showCheckoutForm(){checkoutOpen=true;$("#cartCheckoutFields")?.classList.remove("hidden");$("#beginCheckoutBtn")?.classList.add("hidden");}renderCart=async function(){const host=$("#cartItems");if(!cart.length){checkoutOpen=false;$("#cartCheckoutFields")?.classList.add("hidden");$("#beginCheckoutBtn")?.classList.add("hidden");host.innerHTML='<div class="empty-state">سلة المشتريات فارغة.</div>';$("#cartTotal").textContent="0";$("#cartPaymentInfo").innerHTML="";return;}const rows=cart.map(x=>({...x,p:products.find(p=>p.id===x.id)})).filter(x=>x.p);$("#beginCheckoutBtn")?.classList.toggle("hidden",checkoutOpen);$("#cartCheckoutFields")?.classList.toggle("hidden",!checkoutOpen);host.innerHTML=rows.map(x=>{const mode=x.p.pricing_mode||x.p.currency,unit=x.currency==="USD"?Number(x.p.price_usd||x.p.price):Number(x.p.price_fbt||x.p.price);return `<div class="manage-row cart-row"><div><b>${esc(x.p.name)}</b><small>${unit} ${x.currency} × ${x.quantity}</small>${mode==="BOTH"?`<label class="cart-currency">عملة الشراء<select onchange="setCartCurrency(${x.id},this.value)"><option value="FBT" ${x.currency!=="USD"?"selected":""}>FBT MONEY</option><option value="USD" ${x.currency==="USD"?"selected":""}>الدولار USD</option></select></label>`:""}</div><div class="cart-qty"><button onclick="changeCartQty(${x.id},-1)">−</button><b>${x.quantity}</b><button onclick="changeCartQty(${x.id},1)">＋</button><button class="btn-danger small" onclick="removeCart(${x.id})">×</button></div></div>`}).join("");const totals={FBT:0,USD:0};rows.forEach(x=>{const unit=x.currency==="USD"?Number(x.p.price_usd||x.p.price):Number(x.p.price_fbt||x.p.price);totals[x.currency]+=unit*x.quantity;});$("#cartTotal").textContent=Object.entries(totals).filter(x=>x[1]).map(([c,v])=>v.toLocaleString()+" "+c).join(" + ");const hasUsd=totals.USD>0;$("#cartPayMethod")?.closest("label")?.classList.toggle("hidden",!hasUsd);if(hasUsd){try{const c=await api("/api/store-config");$("#cartPaymentInfo").innerHTML=`<div class="instapay-note"><b>الدفع بالدولار</b><p>رقم التحويل: ${esc(c.instapay_number||"يتم تحديده من الإدارة")}</p><p>اسم المستلم: ${esc(c.instapay_name||"FINAL BREATH STORE")}</p></div>`}catch{}}else $("#cartPaymentInfo").innerHTML="";};
function setCartCurrency(id,currency){const row=cart.find(x=>x.id===id);if(row)row.currency=currency;renderCart();}
const _addCartOriginal=addToCart;addToCart=function(id){const p=products.find(x=>x.id===id);if(!p)return;const row=cart.find(x=>x.id===id);if(row)row.quantity=Math.min(99,row.quantity+1);else cart.push({id,quantity:1,currency:(p.pricing_mode||p.currency)==="USD"?"USD":"FBT"});updateCartCount();toast("تمت إضافة المنتج للسلة");};
checkoutCart=async function(){if(!me){openAuth();return}if(!cart.length)return toast("السلة فارغة");const customer=$("#cartCustomerName").value.trim(),discord=$("#cartDiscord").value.trim(),method=$("#cartPayMethod").value;if(customer.length<2)return toast("اكتب اسمك");if(discord.length<2)return toast("اكتب اسم ديسكورد");const needsExternal=cart.some(x=>{const p=products.find(z=>z.id===x.id);return p&&(x.currency==="USD"||((p.pricing_mode||p.currency)==="USD"));});if(needsExternal&&!method)return toast("اختار طريقة الدفع");const detail=`الاسم: ${customer}\nDiscord: ${discord}\nطريقة الدفع: ${needsExternal?method:"FBT MONEY"}\n${$("#cartDetails").value||""}`;try{const d=await api("/api/cart/orders",{method:"POST",body:JSON.stringify({items:cart,discordName:discord,details:detail,coupon:$("#cartCoupon").value})});cart=[];updateCartCount();await renderCart();toast(d.message);await loadAll();showPage("orders")}catch(e){toast(e.message)}};
async function loadLeaderboards(type="money"){try{const data=await api("/api/leaderboards"),arr=data[type]||[];const host=$("#leaderboardList");host.innerHTML=arr.map((u,i)=>`<div class="leaderboard-row ${i<3?"top-three":""} podium-${i+1} ${String(u.username).toUpperCase()==="HAGED"?"haged-center":""}"><span class="leaderboard-rank">${i===0?"♛ TOP 1":i===1?"TOP 2":i===2?"TOP 3":"#"+(i+1)}</span><b>${esc(u.username)}</b><span>${type==="money"?Number(u.balance).toLocaleString()+" FBT":type==="buys"?Number(u.purchases||0)+" مشتريات":roleName(u.role)}</span></div>`).join("")||'<p class="muted">لا توجد بيانات بعد.</p>';}catch(e){toast(e.message)}}
const _showPageRefined=showPage;showPage=function(name){_showPageRefined(name);if(name==="home")loadLeaderboards("money");if(name==="cart")renderCart();};
const _loadProductsWithRefined=loadProducts;loadProducts=async function(){await _loadProductsWithRefined();renderProducts();};
toggleProductPrices();loadLeaderboards("money");

deleteProduct=async function(id){if(!await fbtConfirm("حذف المنتج نهائيًا من المتجر؟","حذف",true))return;try{await api("/api/admin/products/"+id,{method:"DELETE"});toast("تم حذف المنتج نهائيًا");await loadProducts();if(me?.role==="owner")await loadAdmin();}catch(e){toast(e.message)}};

async function editProductAdvanced(id){const p=(await api("/api/admin/all-products")).find(x=>x.id===id);if(!p)return;const mode=p.pricing_mode||p.currency;openModal(`<h2>تعديل المنتج</h2><form id="editProductForm"><label>اسم المنتج<input name="name" required value="${esc(p.name)}"></label><label>وصف مختصر<textarea name="shortDescription" maxlength="180">${esc(p.short_description||"")}</textarea></label><label>الوصف الكامل<textarea name="description" rows="4">${esc(p.description||"")}</textarea></label><label>نظام السعر<select name="pricingMode" id="editPricingMode" onchange="toggleEditPrices()"><option value="FBT" ${mode==="FBT"?"selected":""}>FBT فقط</option><option value="USD" ${mode==="USD"?"selected":""}>USD فقط</option><option value="BOTH" ${mode==="BOTH"?"selected":""}>الاثنين</option></select></label><label id="editFbtWrap">السعر FBT<input name="priceFbt" type="number" min="1" value="${Number(p.price_fbt||p.price)}"></label><label id="editUsdWrap">السعر بالدولار<input name="priceUsd" type="number" min="0.01" step="0.01" value="${Number(p.price_usd||p.price)}"></label><label>تغيير الصورة (اختياري)<input name="image" type="file" accept="image/png,image/jpeg,image/webp,image/gif"></label><div class="form-two"><label>قص أفقي<input name="cropX" type="range" min="0" max="100" value="${p.crop_x??50}"></label><label>قص رأسي<input name="cropY" type="range" min="0" max="100" value="${p.crop_y??50}"></label></div><button class="btn-main full">حفظ التعديلات</button></form>`);toggleEditPrices();$("#editProductForm").onsubmit=async e=>{e.preventDefault();try{await api("/api/admin/products/"+id,{method:"PATCH",body:new FormData(e.target)});closeModal();toast("تم تحديث المنتج");await loadProducts();await loadAdmin();}catch(err){toast(err.message)}};}
function toggleEditPrices(){const m=$("#editPricingMode")?.value||"FBT";$("#editFbtWrap")?.classList.toggle("hidden",m==="USD");$("#editUsdWrap")?.classList.toggle("hidden",m==="FBT");}


// Seller access is deliberately read-only and limited to products, product orders and coin ledger.
async function loadSellerWorkspace(){
  try{
    const [orders,ledger,productsData]=await Promise.all([
      api("/api/admin/orders"),api("/api/admin/ledger"),api("/api/admin/all-products")
    ]);
    const orderHost=$("#adminOrders");
    if(orderHost) orderHost.innerHTML=orders.map(o=>`<div class="history-row"><div><b>#${o.id} · ${esc(o.product_name)} × ${o.quantity}</b><small>${esc(o.username)} · ${esc(o.discord_name)} · ${esc(o.created_at)}</small><small>${esc(o.details||"")}</small></div><div class="history-meta"><b>${Number(o.total).toLocaleString()} ${esc(o.currency)}</b><span class="status ${esc(o.status)}">${statusLabel(o.status)}</span></div></div>`).join("")||'<div class="empty-state">لا توجد طلبات.</div>';
    const ledgerHost=$("#ledgerList");
    if(ledgerHost) ledgerHost.innerHTML=ledger.map(l=>`<div class="history-row"><div><b>${esc(l.username)}</b><small>${esc(l.reason)} · ${esc(l.created_at)}</small></div><strong class="${l.amount>=0?"positive":"negative"}">${l.amount>0?"+":""}${Number(l.amount).toLocaleString()} FBT</strong></div>`).join("")||'<div class="empty-state compact">لا توجد حركات مسجلة.</div>';
    const productHost=$("#adminProducts");
    if(productHost) productHost.innerHTML=productsData.map(p=>`<div class="manage-row"><div><b>${esc(p.name)}</b><small>${Number(p.price).toLocaleString()} ${esc(p.currency)} · ${p.active?"منشور":"مخفي"}</small></div><span class="muted">عرض فقط</span></div>`).join("")||'<div class="empty-state">لا توجد منتجات.</div>';
  }catch(e){toast(e.message)}
}
showPage=function(name){
  const sellerPages=["owner-products","owner-orders","owner-ledger"];
  const ownerPages=["owner-users","owner-topups","owner-ranks","owner-coupons","owner-settings"];
  if(ownerPages.includes(name)&&me?.role!=="owner"){toast("القسم ده للمالك فقط");return}
  if(sellerPages.includes(name)&&!["owner","seller"].includes(me?.role)){toast("القسم ده للمالك والبائع فقط");return}
  document.querySelectorAll(".page").forEach(p=>p.classList.remove("active"));
  $("#page-"+name)?.classList.add("active");
  document.querySelectorAll(".nav-item").forEach(b=>b.classList.toggle("active",b.dataset.page===name));
  if(name==="orders")loadOrders();if(name==="wallet")loadTopups();if(name==="cart")renderCart();
  if(name.startsWith("owner-")){if(me?.role==="owner")loadAdmin();else loadSellerWorkspace();}
  window.scrollTo({top:0,behavior:"smooth"});
};
function configureSellerNavigation(){
  const isSeller=me?.role==="seller", isOwner=me?.role==="owner";
  const nav=$("#ownerNav"), label=$("#ownerLabel");
  if(!nav)return;
  if(isSeller){
    label.classList.remove("hidden");nav.classList.remove("hidden");
    nav.innerHTML=`<button class="nav-item" data-page="owner-orders" onclick="showPage('owner-orders')"><i>▣</i> طلبات المنتجات</button><button class="nav-item" data-page="owner-products" onclick="showPage('owner-products')"><i>▦</i> المنتجات</button><button class="nav-item" data-page="owner-ledger" onclick="showPage('owner-ledger')"><i>◷</i> سجل العملات</button>`;
    const form=$("#productForm");if(form)form.classList.add("hidden");
    document.querySelectorAll("#ownerNav .nav-item").forEach(b=>b.classList.remove("active"));
  }else if(isOwner){
    nav.querySelectorAll(".nav-item").forEach(b=>b.classList.remove("hidden"));
  }
}
const _renderAccountRoleAware=renderAccount;
renderAccount=function(){_renderAccountRoleAware();configureSellerNavigation();};
const _loadAllRoleAware=loadAll;
loadAll=async function(){await _loadAllRoleAware();if(me?.role==="seller"){configureSellerNavigation();await loadSellerWorkspace();}};

api("/api/me").then(d=>{if(d.user?.role==="seller"){me=d.user;renderAccount();loadSellerWorkspace();}}).catch(()=>{});



// Paid VIP / PREMIUM rank checkout (kept separate from the legacy cart and wallet).
let availableRanks={};
async function loadRanks(){try{availableRanks=await api("/api/ranks");for(const [k,id] of [["VIP","vipRankPrice"],["PREMIUM","premiumRankPrice"]]){const r=availableRanks[k],price=document.getElementById(id),btn=document.getElementById(k.toLowerCase()+"RankBuy");if(price)price.textContent=r&&r.active?`$${Number(r.price).toFixed(2)} USD`:"البيع متوقف";if(btn){btn.disabled=!r||!r.active;btn.textContent=r&&r.active?`شراء ${k}`:"غير متاح حاليًا";}}}catch(e){console.warn(e)}}
function buyRank(key){if(!me){openAuth();return}const r=availableRanks[key];if(!r||!r.active)return toast("الرتبة غير متاحة للبيع حاليًا");openModal(`<div class="modal-kicker">FBT MEMBERSHIP</div><h2>شراء رتبة ${esc(r.name)}</h2><p class="muted">السعر النهائي: <b>$${Number(r.price).toFixed(2)} USD</b>. سيتم إرسال الطلب للمالك، ولن تُمنح الرتبة قبل الموافقة.</p><form id="rankPurchaseForm"><label>اسمك على Discord<input name="discordName" required maxlength="80" placeholder="Discord username"></label><label>Discord User ID<input name="discordUserId" required inputmode="numeric" pattern="[0-9]{17,20}" placeholder="مثال: 123456789012345678"><small class="muted">مطلوب عشان البوت يقدر يضيف الرتبة لحسابك الصحيح.</small></label><label>طريقة الدفع<select name="method" required><option value="">اختار طريقة الدفع</option><option>Vodafone Cash</option><option>InstaPay</option><option>PayPal</option><option>تحويل بنكي</option><option>طريقة أخرى</option></select></label><label>إثبات الدفع (صورة)<input name="proof" type="file" accept="image/png,image/jpeg,image/webp,image/gif" required></label><div class="order-total"><span>الرتبة المطلوبة</span><b>${esc(r.name)} · $${Number(r.price).toFixed(2)}</b></div><button class="btn-main full">إرسال طلب الشراء ←</button></form>`);document.getElementById("rankPurchaseForm").onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target);fd.set("rank",key);const btn=e.target.querySelector("button[type=submit],button:not([type])");if(btn)btn.disabled=true;try{const d=await api("/api/rank-orders",{method:"POST",body:fd});closeModal();toast(d.message);}catch(err){toast(err.message);if(btn)btn.disabled=false;}}}
async function loadRankOrders(){const host=document.getElementById("adminRankOrders");if(!host)return;try{const rows=await api("/api/admin/rank-orders");host.innerHTML=rows.map(o=>`<div class="history-row"><div><b>#${o.id} · ${esc(o.rank_name)} · $${Number(o.total_usd).toFixed(2)}</b><small>${esc(o.username)} · Discord: ${esc(o.discord_name)} · ID: ${esc(o.discord_user_id)}</small><small>طريقة الدفع: ${esc(o.payment_method)} · ${esc(o.created_at)}</small><small><a href="${esc(o.proof)}" target="_blank" rel="noopener">فتح إثبات الدفع</a></small></div><div class="history-meta"><span class="status ${esc(o.status)}">${statusLabel(o.status)}</span>${o.status==="pending"?`<div class="rank-review-actions"><button class="btn-main small" onclick="reviewRankOrder(${o.id},'accept')">موافقة</button><button class="btn-danger small" onclick="reviewRankOrder(${o.id},'reject')">رفض</button></div>`:""}</div></div>`).join("")||'<div class="empty-state">لا توجد طلبات رتب حتى الآن.</div>';}catch(e){host.innerHTML=`<div class="empty-state">${esc(e.message)}</div>`}}
async function reviewRankOrder(id,action){const label=action==="accept"?"قبول الطلب ومنح الرتبة على Discord والموقع؟":"رفض الطلب؟";if(!await fbtConfirm(label,action==="accept"?"موافقة":"رفض",action==="reject"))return;try{const d=await api(`/api/admin/rank-orders/${id}/review`,{method:"POST",body:JSON.stringify({action})});toast(d.message);await loadRankOrders();}catch(e){toast(e.message)}}
const _loadAdminForRanks=loadAdmin;loadAdmin=async function(){await _loadAdminForRanks();await loadRankOrders();};
